package com.xiahu.reader;
import android.app.*;
import android.os.Bundle;
import org.json.*;
import java.util.concurrent.atomic.AtomicInteger;

public final class TagTest extends Instrumentation {
    static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
    static final class Source implements TagCatalog.Source {
        final AtomicInteger calls=new AtomicInteger(),active=new AtomicInteger(),maximum=new AtomicInteger();
        public JSONObject page(int n)throws Exception{calls.incrementAndGet();int current=active.incrementAndGet();maximum.updateAndGet(v->Math.max(v,current));Thread.sleep(20);active.decrementAndGet();return new JSONObject().put("pages",24).put("books",new JSONArray().put(new JSONObject().put("id",n).put("title","Original "+n).put("author",n%2==0?"Author A":"Author B").put("tags",n==24?"校园 伪娘":"校园 魔法").put("updated","2026-10-28")));}
    }
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle out=new Bundle();TagCatalog tags=null;
        try{
            getTargetContext().deleteFile("tag_test_only.json");Source source=new Source();tags=new TagCatalog(getTargetContext(),source,"tag_test_only.json");JSONArray rare=new JSONArray().put("伪娘");JSONObject result=tags.query(rare,"all","",30,true,false);check(!result.getBoolean("complete"),"Empty initial result is not a complete search");
            long until=System.currentTimeMillis()+20000;while(tags.status().getBoolean("running")&&System.currentTimeMillis()<until)Thread.sleep(50);result=tags.query(rare,"all","",30,false,false);check(result.getBoolean("complete")&&result.getInt("totalMatches")==1&&result.getJSONArray("books").getJSONObject(0).getInt("id")==24,"Rare final-page tag found without manual refresh");
            check(tags.query(new JSONArray().put("伪娘").put("魔法"),"all","",30,false,false).getInt("totalMatches")==0,"ALL applies every term");check(tags.query(new JSONArray().put("伪娘").put("魔法"),"any","",30,false,false).getInt("totalMatches")==24,"ANY is a deduplicated union");check(tags.query(rare,"all","Author A",30,false,false).getInt("totalMatches")==1,"Text and tag filters combine");
            int calls=source.calls.get();tags.close();tags=new TagCatalog(getTargetContext(),source,"tag_test_only.json");check(tags.query(rare,"all","",30,true,false).getInt("totalMatches")==1&&source.calls.get()==calls,"Persistent complete index avoids repeated scans");check(source.maximum.get()<=2,"At most two metadata requests at once");
            tags.start(true);long pauseUntil=System.currentTimeMillis()+5000;while(tags.status().getInt("scannedPages")<3&&System.currentTimeMillis()<pauseUntil)Thread.sleep(20);tags.pause();while(tags.status().getBoolean("running"))Thread.sleep(20);int scanned=tags.status().getInt("scannedPages");check(scanned>=3&&scanned<24,"Partial index can pause before completion");tags.close();tags=new TagCatalog(getTargetContext(),source,"tag_test_only.json");check(tags.status().getInt("scannedPages")==scanned&&!tags.status().getBoolean("complete"),"Incomplete cursor survives process recreation");
            tags.close();getTargetContext().deleteFile("tag_quick_test_only.json");AtomicInteger quickCalls=new AtomicInteger();
            TagCatalog.Source slow=n->{Thread.sleep(100);return new JSONObject().put("pages",400).put("books",new JSONArray().put(new JSONObject().put("id",200000+n).put("title","Catalog "+n).put("tags","校园")));};
            TagCatalog.QuickSource quick=term->{quickCalls.incrementAndGet();return new JSONObject().put("books",new JSONArray().put(new JSONObject().put("id",700001).put("title","Original 妹妹").put("author","A").put("tags","妹妹 校园")).put(new JSONObject().put("id",700002).put("title","妹妹 in title only").put("author","B").put("tags","恋爱")));};
            tags=new TagCatalog(getTargetContext(),slow,quick,"tag_quick_test_only.json");JSONArray sister=new JSONArray().put("妹妹");tags.query(sister,"all","",30,true,false);long fastUntil=System.currentTimeMillis()+3000;while(tags.status().getInt("quickFinished")==0&&System.currentTimeMillis()<fastUntil)Thread.sleep(20);JSONObject fast=tags.query(sister,"all","",30,true,false);check(fast.getInt("totalMatches")==1&&fast.getJSONArray("books").getJSONObject(0).getInt("id")==700001&&!fast.getBoolean("complete")&&fast.getInt("scannedPages")<10,"Verified tag hit appears before 400-page completion, not a title-only false match");check(quickCalls.get()==1,"Repeated polls reuse quick query");check(tags.query(new JSONArray().put("妹妹").put("校园"),"all","",30,false,false).getInt("totalMatches")==1,"Quick candidates obey ALL");check(tags.query(new JSONArray().put("妹妹").put("恋爱"),"any","",30,false,false).getInt("totalMatches")==2,"Quick candidates obey ANY without duplicates");tags.pause();while(tags.status().getBoolean("running"))Thread.sleep(20);tags.close();tags=new TagCatalog(getTargetContext(),slow,quick,"tag_quick_test_only.json");check(tags.query(sister,"all","",30,false,false).getInt("totalMatches")==1&&!tags.status().getBoolean("complete"),"Quick metadata persists without claiming full coverage");
            out.putString("report",new JSONObject().put("passed",true).put("verifiedQuickTagBeforeFullScan",true).put("titleOnlyFalseMatchExcluded",true).put("quickQueryDeduplicated",true).put("quickPartialMetadataPersists",true).put("rareLastPageTagFoundAutomatically",true).put("allAnyAndTextIntersection",true).put("completeDistinguishedFromInitialEmpty",true).put("persistentIndexNoRescan",true).put("partialCursorPersistsAfterPause",true).put("metadataConcurrencyMaxTwo",true).put("sourceCalls",calls).put("fixture","original metadata only; no source server requests").toString());finish(Activity.RESULT_OK,out);
        }catch(Throwable e){out.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,out);}finally{if(tags!=null)tags.close();getTargetContext().deleteFile("tag_test_only.json");getTargetContext().deleteFile("tag_quick_test_only.json");}
    }
}
